<script setup lang="ts">const route=useRoute(); const platform=usePlatformApi(); const id=String(route.params.id); const {data:task,pending,error}=await useAsyncData(`proposal-task-${id}`,()=>platform.getTask(id));</script>
<template><div class="page"><NuxtLink to="/tasks" class="back-link">К моим задачам</NuxtLink><p v-if="pending">Загрузка…</p><p v-else-if="error" class="error-text">Не удалось загрузить задачу.</p><template v-else-if="task"><div class="page-heading"><div><h1>Предложения команд<span class="heading-dot">.</span></h1><p>{{ task.card.title }}</p></div></div><ProposalList :task-id="id" /></template></div></template>
